from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# CUDA kernel (uses WMMA / Tensor Cores) for fp16 batched GEMM
# ----------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <mma.h>

using namespace nvcuda;

#define TILE_M 16
#define TILE_N 16
#define TILE_K 16

// ---------------------------------------------------------------
// Kernel: each block computes a 16x16 tile of C for a given batch
// ---------------------------------------------------------------
__global__ void batched_gemm_fp16_kernel(const half* __restrict__ A,
                                         const half* __restrict__ B,
                                         half* __restrict__ C,
                                         int M, int N, int K) {
    int batch_id   = blockIdx.x;
    int tile_row   = blockIdx.y;
    int tile_col   = blockIdx.z;

    int row = tile_row * TILE_M;
    int col = tile_col * TILE_N;

    const half* A_batch = A + batch_id * M * K;
    const half* B_batch = B + batch_id * K * N;
    half*       C_batch = C + batch_id * M * N;

    // shared memory tiles
    __shared__ half As[TILE_M][TILE_K];
    __shared__ half Bs[TILE_K][TILE_N];

    // accumulator fragment (fp32)
    wmma::fragment<wmma::accumulator, TILE_M, TILE_N, TILE_K, float> c_frag;
    wmma::fill_fragment(c_frag, 0.0f);

    // loop over K dimension tiles
    for (int tk = 0; tk < K / TILE_K; ++tk) {
        // load A tile (row‑major)
        int a_row = row + threadIdx.y;
        int a_col = tk * TILE_K + threadIdx.x;
        As[threadIdx.y][threadIdx.x] = A_batch[a_row * K + a_col];

        // load B tile (row‑major)
        int b_row = tk * TILE_K + threadIdx.y;
        int b_col = col + threadIdx.x;
        Bs[threadIdx.y][threadIdx.x] = B_batch[b_row * N + b_col];

        __syncthreads();

        // load fragments from shared memory
        wmma::fragment<wmma::matrix_a, TILE_M, TILE_N, TILE_K, half, wmma::row_major> a_frag;
        wmma::fragment<wmma::matrix_b, TILE_M, TILE_N, TILE_K, half, wmma::row_major> b_frag;

        wmma::load_matrix_sync(a_frag, &As[0][0], TILE_K);
        wmma::load_matrix_sync(b_frag, &Bs[0][0], TILE_N);

        // matrix multiply‑accumulate
        wmma::mma_sync(c_frag, a_frag, b_frag, c_frag);

        __syncthreads();
    }

    // write result back to global memory (fp16)
    if (row < M && col < N) {
        wmma::store_matrix_sync(&C_batch[row * N + col], c_frag, N, wmma::mem_row_major);
    }
}

// ----------------------------------------------------------------------
// Python‑callable wrapper
// ----------------------------------------------------------------------
void batched_gemm_fp16(torch::Tensor A, torch::Tensor B, torch::Tensor C) {
    const int batch = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    const int N = B.size(2);

    dim3 grid(batch,
              (M + TILE_M - 1) / TILE_M,
              (N + TILE_N - 1) / TILE_N);
    dim3 block(TILE_K, TILE_M);   // 16 × 16 threads

    batched_gemm_fp16_kernel<<<grid, block>>>(
        reinterpret_cast<const half*>(A.data_ptr()),
        reinterpret_cast<const half*>(B.data_ptr()),
        reinterpret_cast<half*>(C.data_ptr()),
        M, N, K);
    cudaDeviceSynchronize();
}
'''

# Compile the extension
ext = load_inline(name='batched_gemm',
                  cpp_sources='',
                  cuda_sources=cuda_source,
                  functions=['batched_gemm_fp16'],
                  verbose=False)

# ----------------------------------------------------------------------
# Autograd Function using the custom kernel for forward,
# and torch's native bmm for backward (ensures correct gradients)
# ----------------------------------------------------------------------
class BatchedGemmFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, A, B):
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float16 and B.dtype == torch.float16, "Only fp16 supported"
        batch, M, K = A.shape
        _, K2, N = B.shape
        assert K == K2, "Incompatible inner dimensions"

        C = torch.empty((batch, M, N), device=A.device, dtype=torch.float16)
        ext.batched_gemm_fp16(A, B, C)

        ctx.save_for_backward(A, B)
        return C

    @staticmethod
    def backward(ctx, grad_output):
        A, B = ctx.saved_tensors
        # grad w.r.t A: dA = grad_output @ B^T
        grad_A = torch.bmm(grad_output, B.transpose(1, 2))
        # grad w.r.t B: dB = A^T @ grad_output
        grad_B = torch.bmm(A.transpose(1, 2), grad_output)
        return grad_A, grad_B

# ----------------------------------------------------------------------
# Model wrapper exposing the same interface as the reference implementation
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference Model using a custom CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return BatchedGemmFunction.apply(A, B)

# ----------------------------------------------------------------------
# Helper functions matching the reference script
# ----------------------------------------------------------------------
def get_inputs():
    batch_size = 128
    m = 128 * 4
    k = 256 * 4
    n = 512 * 4
    A = torch.rand(batch_size, m, k, device='cuda', dtype=torch.float16)
    B = torch.rand(batch_size, k, n, device='cuda', dtype=torch.float16)
    return [A, B]

def get_init_inputs():
